#include <string>
#include <vector>
#include <unordered_map>
#include <set>

class EventManager {
    std::unordered_map<std::string, std::set<int>> events;
public:
    EventManager() {}

    void subscribe(std::string event, int listenerId) {
        events[event].insert(listenerId);
    }

    void unsubscribe(std::string event, int listenerId) {
        if (events.count(event)) {
            events[event].erase(listenerId);
        }
    }

    std::vector<int> emit(std::string event) {
        if (!events.count(event)) return {};
        return std::vector<int>(events[event].begin(), events[event].end());
    }
};

import java.util.*;

class EventManager {
    private Map<String, TreeSet<Integer>> events = new HashMap<>();

    public EventManager() {}

    public void subscribe(String event, int listenerId) {
        events.computeIfAbsent(event, k -> new TreeSet<>()).add(listenerId);
    }

    public void unsubscribe(String event, int listenerId) {
        if (events.containsKey(event)) {
            events.get(event).remove(listenerId);
        }
    }

    public List<Integer> emit(String event) {
        if (!events.containsKey(event)) return Collections.emptyList();
        return new ArrayList<>(events.get(event));
    }
}

class EventManager {
    constructor() {
        this.events = new Map();
    }

    subscribe(event, listenerId) {
        if (!this.events.has(event)) {
            this.events.set(event, new Set());
        }
        this.events.get(event).add(listenerId);
    }

    unsubscribe(event, listenerId) {
        if (this.events.has(event)) {
            this.events.get(event).delete(listenerId);
        }
    }

    emit(event) {
        if (!this.events.has(event)) return [];
        return Array.from(this.events.get(event)).sort((a, b) => a - b);
    }
}
